args:
set -e

PAGES_URL="{{inputs.parameters.pages-url}}"
echo "Running Lighthouse CI gate against: $PAGES_URL"

# Install Lighthouse CLI
npm install -g lighthouse

# Run Lighthouse and output JSON
lighthouse "$PAGES_URL" \
  --quiet \
  --chrome-flags="--headless --no-sandbox --disable-gpu" \
  --output=json \
  --output-path=/tmp/lighthouse-report

# Parse scores from JSON output and validate thresholds
SCORES=$(node -e "
const fs = require('fs');
const report = JSON.parse(fs.readFileSync('/tmp/lighthouse-report', 'utf8'));
const perf = report.categories.performance.score * 100;
const a11y = report.categories.accessibility.score * 100;
const best = report.categories['best-practices'].score * 100;
const seo = report.categories.seo.score * 100;

console.log(\`Performance: \${perf}\nAccessibility: \${a11y}\nBest Practices: \${best}\nSEO: \${seo}\`);

const MIN_SCORE = 95;
let failed = false;
if (perf < MIN_SCORE) { console.error('FAIL: Performance ' + perf + ' < ' + MIN_SCORE); failed = true; }
if (a11y < MIN_SCORE) { console.error('FAIL: Accessibility ' + a11y + ' < ' + MIN_SCORE); failed = true; }
if (best < MIN_SCORE) { console.error('FAIL: Best Practices ' + best + ' < ' + MIN_SCORE); failed = true; }
if (seo < MIN_SCORE) { console.error('FAIL: SEO ' + seo + ' < ' + MIN_SCORE); failed = true; }

if (failed) process.exit(1);
console.log('All Lighthouse scores passed minimum threshold of ' + MIN_SCORE);
")

echo "Lighthouse CI gate passed"

import hashlib
import json
import os
import subprocess
from datetime import datetime, timezone

TAG = "{{workflow.parameters.tag}}"
VERSION = "{{workflow.parameters.version}}"
COMMIT_SHA = "{{workflow.parameters.commit-sha}}"
REPO = "{{workflow.parameters.repo}}"
BUILD_TYPE = "https://argoproj.io/argo-workflows@v1"
BUILDER_ID = "https://iad-ci-oidc.ardenone.com/argo-workflows/pdftract-release-cascade"

# Artifact directory
artifacts_dir = "/artifacts"

# Generate SOURCE_DATE_EPOCH for reproducibility
SOURCE_DATE_EPOCH = subprocess.check_output(
    ["git", "show", "-s", "--format=%ct", COMMIT_SHA],
    cwd="/workspace"
).decode().strip()

# Collect all binary archives
subjects = []
for root, dirs, files in os.walk(artifacts_dir):
    for f in files:
        if f.endswith((".tar.gz", ".zip")):
            path = os.path.join(root, f)
            # Compute SHA256
            sha256 = hashlib.sha256()
            with open(path, "rb") as fp:
                for chunk in iter(lambda: fp.read(65536), b""):
                    sha256.update(chunk)
            digest = sha256.hexdigest()
            subjects.append({
                "name": f,
                "digest": {"sha256": digest}
            })
            print(f"Subject: {f} -> sha256:{digest}")

# Compute Cargo.lock hash
cargo_lock_path = "/workspace/Cargo.lock"
cargo_lock_hash = None
if os.path.exists(cargo_lock_path):
    sha256 = hashlib.sha256()
    with open(cargo_lock_path, "rb") as fp:
        for chunk in iter(lambda: fp.read(65536), b""):
            sha256.update(chunk)
    cargo_lock_hash = sha256.hexdigest()
    print(f"Cargo.lock: sha256:{cargo_lock_hash}")

# Build resolved dependencies
resolved_deps = [
    {
        "uri": f"git+https://github.com/{REPO}@{COMMIT_SHA}",
        "digest": {"gitCommit": COMMIT_SHA}
    }
]
if cargo_lock_hash:
    resolved_deps.append({
        "uri": "Cargo.lock",
        "digest": {"sha256": cargo_lock_hash}
    })

# Build invocation ID (reproducible from commit)
invocation_id = f"argo-workflows-{COMMIT_SHA}-{TAG}"

# Build timestamp from SOURCE_DATE_EPOCH
started_on = datetime.fromtimestamp(int(SOURCE_DATE_EPOCH), tz=timezone.utc).isoformat()
finished_on = datetime.now(timezone.utc).isoformat()

# Construct SLSA Provenance v1.0 predicate
provenance = {
    "_type": "https://in-toto.io/Statement/v1",
    "subject": subjects,
    "predicateType": "https://slsa.dev/provenance/v1.0",
    "predicate": {
        "buildDefinition": {
            "buildType": BUILD_TYPE,
            "externalParameters": {
                "tag": TAG,
                "version": VERSION,
                "commit": COMMIT_SHA,
                "source": f"https://github.com/{REPO}"
            },
            "internalParameters": {
                "workflow": "pdftract-build-binaries",
                "targetTriples": [
                    "x86_64-unknown-linux-musl",
                    "aarch64-unknown-linux-musl",
                    "x86_64-apple-darwin",
                    "aarch64-apple-darwin",
                    "x86_64-pc-windows-gnu"
                ]
            },
            "resolvedDependencies": resolved_deps
        },
        "runDetails": {
            "builder": {
                "id": BUILDER_ID,
                "builderDependencies": [],
                "version": {
                    "argo": "v3.5.x"
                }
            },
            "metadata": {
                "invocationId": invocation_id,
                "startedOn": started_on,
                "finishedOn": finished_on
            },
            "byproducts": []
        }
    }
}

# Write to multiple.intoto.jsonl (one JSON per line)
output_path = "/provenance/multiple.intoto.jsonl"
os.makedirs(os.path.dirname(output_path), exist_ok=True)
with open(output_path, "w") as f:
    f.write(json.dumps(provenance) + "\n")

print(f"Provenance written to {output_path}")
print(f"Subjects: {len(subjects)}")
print(f"Invocation ID: {invocation_id}")

